describe('View Item Details', () => {
  beforeEach(() => {
    cy.visit('/items');
  });

  it('should successfully display item details when clicking on an item', () => {
    // Intercept the API call to get item details
    cy.intercept('GET', '/api/items/123').as('getItemDetails');

    // Verify the item is visible in the list
    cy.get('[data-testid="item-list"]').should('be.visible');
    cy.get('[data-testid="item-name-123"]').should('contain', 'Sample Item');

    // Click on the item to view details
    cy.get('[data-testid="item-name-123"]').click();

    // Wait for the API call to complete
    cy.wait('@getItemDetails');

    // Verify the details modal is visible
    cy.get('[data-testid="item-details-modal"]').should('be.visible');

    // Verify the title is displayed
    cy.get('[data-testid="item-details-title"]').should('contain', 'Sample Item Details');

    // Verify the description is displayed
    cy.get('[data-testid="item-description"]').should('be.visible');
    cy.get('[data-testid="item-description"]').should('contain', 'This is a sample item description');

    // Verify the price is displayed
    cy.get('[data-testid="item-price"]').should('be.visible');
    cy.get('[data-testid="item-price"]').should('contain', '$19.99');

    // Verify the image is displayed
    cy.get('[data-testid="item-image"]').should('be.visible');
    cy.get('[data-testid="item-image"]').should('have.attr', 'src');

    // Verify the close button is present
    cy.get('[data-testid="item-details-close-btn"]').should('be.visible');

    // Verify the modal closes when close button is clicked
    cy.get('[data-testid="item-details-close-btn"]').click();
    cy.get('[data-testid="item-details-modal"]').should('not.exist');
  });

  it('should handle empty item list and display error message', () => {
    // Intercept the API call to get empty item list
    cy.intercept('GET', '/api/items/empty').as('getEmptyItemList');

    // Verify the item list is empty
    cy.get('[data-testid="item-list"]').should('be.visible');
    cy.get('[data-testid="item-name-123"]').should('not.exist');

    // Click on an empty item to trigger the API call
    cy.get('[data-testid="item-list"]').click();

    // Wait for the API call to complete
    cy.wait('@getEmptyItemList');

    // Verify the error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'No items found');

    // Verify the item list still exists
    cy.get('[data-testid="item-list"]').should('be.visible');

    // Verify the empty state message is displayed
    cy.get('[data-testid="empty-state-message"]').should('be.visible');
    cy.get('[data-testid="empty-state-message"]').should('contain', 'No items available');

    // Verify the back button is still functional
    cy.get('[data-testid="back-btn"]').should('be.visible');
    cy.get('[data-testid="back-btn"]').click();

    // Verify the item list is restored
    cy.get('[data-testid="item-list"]').should('be.visible');
  });
});
